export class Hono<
  E extends Env = BlankEnv,
  S extends Schema = BlankSchema,
  BasePath extends string = '/',
> extends HonoBase<E, S, BasePath> {
  constructor(options: HonoOptions<E> = {}) {
    super(options)
    this.router =
      options.router ??
      new SmartRouter({
        routers: [new RegExpRouter(), new TrieRouter()],
      })
  }
}

#addRoute(method: string, path: string, handler: H, baseRoutePath?: string): void {
  path = mergePath(this._basePath, path)
  const r: RouterRoute = {
    basePath:
      baseRoutePath !== undefined ? mergePath(this._basePath, baseRoutePath) : this._basePath,
    path,
    method,
    handler,
  }
  this.router.add(method, path, [handler, r])
  this.routes.push(r)
}

#dispatch(request, executionCtx, env, method) {
  if (method === 'HEAD') {
    return (async () =>
      new Response(null, await this.#dispatch(request, executionCtx, env, 'GET')))()
  }
  const path = this.getPath(request, { env })
  const matchResult = this.router.match(method, path)
  const c = new Context(request, { path, matchResult, env, executionCtx,
    notFoundHandler: this.#notFoundHandler })
  if (matchResult[0].length === 1) {
    // ... call single handler directly ...
  }
  const composed = compose(matchResult[0], this.errorHandler, this.#notFoundHandler)
  return (async () => { const context = await composed(c); return context.res })()
}

async function dispatch(i: number): Promise<Context> {
  if (i <= index) throw new Error('next() called multiple times')
  index = i
  const handler = middleware[i] ? (context.req.routeIndex = i, middleware[i][0][0])
    : (i === middleware.length && next) || undefined
  if (handler) {
    try { res = await handler(context, () => dispatch(i + 1)) }
    catch (err) { if (err instanceof Error && onError) res = await onError(err, context) }
  } else if (!context.finalized && onNotFound) res = await onNotFound(context)
  if (res && (!context.finalized || isError)) context.res = res
  return context
}

#newResponse(data, arg, headers) {
  let responseHeaders = this.#res ? new Headers(this.#res.headers) : this.#preparedHeaders
  if (typeof arg === 'object' && arg.headers) {
    responseHeaders ??= new Headers()
    for (const [key, value] of new Headers(arg.headers)) {
      if (key === 'set-cookie') { responseHeaders.append(key, value) }
      else { responseHeaders.set(key, value) }
    }
  }
  // ... merge per-call headers ...
  const status = typeof arg === 'number' ? arg : (arg?.status ?? this.#status)
  return createResponseInstance(data, { status, headers: responseHeaders ?? ... })
}

export class HTTPException extends Error {
  readonly res?: Response
  readonly status: ContentfulStatusCode
  constructor(status: ContentfulStatusCode = 500, options?: HTTPExceptionOptions) {
    super(options?.message, { cause: options?.cause })
    this.res = options?.res
    this.status = status
  }
  getResponse(): Response {
    if (this.res) {
      return new Response(this.res.body, { status: this.status, headers: this.res.headers })
    }
    return new Response(this.message, { status: this.status })
  }
}

buildRegExp(): [RegExp, ReplacementMap, ReplacementMap] {
  let regexp = this.#root.buildRegExpStr()
  let captureIndex = 0
  const indexReplacementMap: ReplacementMap = []
  const paramReplacementMap: ReplacementMap = []
  regexp = regexp.replace(/#(\d+)|@(\d+)|\.\*\$/g, (_, h, p) => {
    if (h !== undefined) { indexReplacementMap[++captureIndex] = Number(h); return '$()' }
    if (p !== undefined) { paramReplacementMap[Number(p)] = ++captureIndex; return '' }
    return ''
  })
  return [new RegExp(`^${regexp}`), indexReplacementMap, paramReplacementMap]
}

export function match<R extends Router<T>, T>(this: R, method: string, path: string): Result<T> {
  const matchers: MatcherMap<T> = (this as any).buildAllMatchers()
  const match = ((method, path) => {
    const matcher = (matchers[method] || matchers[METHOD_NAME_ALL]) as Matcher<T>
    const staticMatch = matcher[2][path]
    if (staticMatch) { return staticMatch }
    const match = path.match(matcher[0])
    if (!match) { return [[], emptyParam] }
    const index = match.indexOf('', 1)
    return [matcher[1][index], match]
  }) as Router<T>['match']
  this.match = match
  return match(method, path)
}

match(method: string, path: string): Result<T> {
  for (let i = 0; i < this.#routers.length; i++) {
    try {
      for (const r of this.#routes!) this.#routers[i].add(...r)
      res = this.#routers[i].match(method, path)
    } catch (e) {
      if (e instanceof UnsupportedPathError) continue
      throw e
    }
    this.match = this.#routers[i].match.bind(this.#routers[i])
    this.#routes = undefined
    break
  }
  return res
}

